const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, terminal: false });
let inputLines = [];
rl.on('line', (line) => inputLines.push(line));
rl.on('close', () => {
  const data = inputLines.join(' ').split(/\s+/).filter(x => x.length > 0).map(Number);
  let idx = 0;
  const n = data[idx++];
  const t = new Array(101).fill(0);
  for (let i = 1; i <= n; i++) t[i] = data[idx++];

  const UP = 0, DOWN = 1, LEFT = 2, RIGHT = 3;
  const UPLEFT = 4, UPRIGHT = 5, DOWNLEFT = 6, DOWNRIGHT = 7;
  const dx = [0, 0, -1, 1, -1, 1, -1, 1];
  const dy = [1, -1, 0, 0, 1, 1, -1, -1];

  const MAX = 5 * 30 + 5;
  const DIM = 2 * MAX;

  function rot(dir) {
    switch (dir) {
      case UP: return [UPLEFT, UPRIGHT];
      case DOWN: return [DOWNLEFT, DOWNRIGHT];
      case LEFT: return [UPLEFT, DOWNLEFT];
      case RIGHT: return [UPRIGHT, DOWNRIGHT];
      case UPLEFT: return [UP, LEFT];
      case UPRIGHT: return [UP, RIGHT];
      case DOWNLEFT: return [DOWN, LEFT];
      case DOWNRIGHT: return [DOWN, RIGHT];
    }
  }

  const size = DIM * DIM * 8 * 32 * 6;
  const marked = new Uint8Array(size);

  function midx(x, y, dir, lev, far) {
    return (((x * DIM + y) * 8 + dir) * 32 + lev) * 6 + far;
  }

  const mp = new Map();

  let queueX = [];
  let queueY = [];
  let queueDir = [];
  let queueLev = [];
  let queueFar = [];
  let head = 0;

  function pushNode(x, y, dir, lev, far) {
    queueX.push(x);
    queueY.push(y);
    queueDir.push(dir);
    queueLev.push(lev);
    queueFar.push(far);
  }

  let ans = 0;

  pushNode(MAX, MAX, UP, 1, 1);
  marked[midx(MAX, MAX, UP, 1, 1)] = 1;
  mp.set(MAX + ',' + MAX, true);
  ans++;

  while (head < queueX.length) {
    const x = queueX[head];
    const y = queueY[head];
    const dir = queueDir[head];
    const lev = queueLev[head];
    const far = queueFar[head];
    head++;

    const key = x + ',' + y;
    if (!mp.get(key)) {
      mp.set(key, true);
      ans++;
    }

    let x2 = x, y2 = y;

    if (lev === n + 1) continue;

    if (far !== t[lev]) {
      x2 += dx[dir];
      y2 += dy[dir];
      const idx2 = midx(x2, y2, dir, lev, far + 1);
      if (marked[idx2]) continue;
      marked[idx2] = 1;
      pushNode(x2, y2, dir, lev, far + 1);
    } else {
      const dirs = rot(dir);
      const idx1 = midx(x, y, dirs[0], lev + 1, 0);
      if (!marked[idx1]) {
        marked[idx1] = 1;
        pushNode(x, y, dirs[0], lev + 1, 0);
      }
      const idx2b = midx(x, y, dirs[1], lev + 1, 0);
      if (!marked[idx2b]) {
        marked[idx2b] = 1;
        pushNode(x, y, dirs[1], lev + 1, 0);
      }
    }
  }

  console.log(ans);
});
